/**
 * Oberklasse für deterministische endliche Automaten, die als Code programmiert sind.
 * Was bei JEDEM Automaten gleich ist, steht hier: der aktuelle Zustand und das Prüfen eines Worts.
 * Was jeder Automat anders macht (Übergänge, Endzustände), legt die Unterklasse fest.
 * Muss nicht verändert werden.
 */
public abstract class DEA {
   protected int zustand;            // aktueller Zustand: 0 steht für Z0, 1 für Z1, …
   protected final int ZF = 99;      // Fangzustand: eine Nummer, die kein anderer Zustand hat

   // ② Ein Zeichen lesen und dem passenden Pfeil folgen. Jede Unterklasse legt das selbst fest.
   public abstract void zustandWechseln(char zeichen);

   // ④ Steht der Automat in einem Endzustand? Jede Unterklasse legt das selbst fest.
   public abstract boolean istEndzustand();

   // Prüft, ob wort zur Sprache gehört (die vier Regeln von Blatt 1.5).
   public boolean pruefe(String wort) {
      zustand = 0;                                  // ① Start im Startzustand Z0
      for (int i = 0; i < wort.length(); i++) {     // ③ Zeichen für Zeichen lesen
         zustandWechseln(wort.charAt(i));           // ② dem Pfeil folgen
      }
      return istEndzustand();                       // ④ RZK leer: Endzustand?
   }

   // Wie pruefe, gibt aber die Folge der Zustände aus, z. B.  ab1: Z0 Z1 Z1 Z1  ->  akzeptiert
   public void zeigeLauf(String wort) {
      zustand = 0;
      String folge = name(zustand);
      for (int i = 0; i < wort.length(); i++) {
         zustandWechseln(wort.charAt(i));
         folge = folge + " " + name(zustand);
      }
      String ergebnis = "abgelehnt";
      if (istEndzustand()) {
         ergebnis = "akzeptiert";
      }
      String anzeige = wort;
      if (wort.length() == 0) {
         anzeige = "(leeres Wort)";
      }
      println(anzeige + ": " + folge + "  ->  " + ergebnis);
   }

   private String name(int z) {
      if (z == ZF) {
         return "ZF";
      }
      return "Z" + z;
   }
}

/**
 * Aufgabe 1: Erkennt Namen (Bezeichner) wie in Java, vereinfacht:
 * zuerst ein Buchstabe, danach beliebig viele Buchstaben oder Ziffern.
 * Bezeichner = Buchstabe {Buchstabe | Ziffer}.
 * Fertig: nur lesen, nicht verändern.
 */
public class Bezeichner extends DEA {

   public void zustandWechseln(char zeichen) {
      switch (zustand) {
         case 0:
            if (Character.isLetter(zeichen)) {
               zustand = 1;
            } else {
               zustand = ZF;
            }
            break;
         case 1:
            if (Character.isLetterOrDigit(zeichen)) {
               zustand = 1;
            } else {
               zustand = ZF;
            }
            break;
         default:
            zustand = ZF;
      }
   }

   public boolean istEndzustand() {
      return zustand == 1;
   }
}

/**
 * Aufgabe 2: Erkennt Kommazahlen wie in Java, vereinfacht: 42, 3.14, 0.5
 * (ohne Vorzeichen; 3. und .5 sind hier nicht erlaubt).
 * LÖSUNG (Lehrkräfte)
 */
public class Kommazahl extends DEA {

   public void zustandWechseln(char zeichen) {
      switch (zustand) {
         case 0:
            if (Character.isDigit(zeichen)) {
               zustand = 1;
            } else {
               zustand = ZF;
            }
            break;
         case 1:
            if (Character.isDigit(zeichen)) {
               zustand = 1;
            } else if (zeichen == '.') {      // TODO 2a
               zustand = 2;
            } else {
               zustand = ZF;
            }
            break;
         case 2:                              // TODO 2b
            if (Character.isDigit(zeichen)) {
               zustand = 3;
            } else {
               zustand = ZF;
            }
            break;
         case 3:
            if (Character.isDigit(zeichen)) {
               zustand = 3;
            } else {
               zustand = ZF;
            }
            break;
         default:
            zustand = ZF;
      }
   }

   public boolean istEndzustand() {
      return zustand == 1 || zustand == 3;    // TODO 2c
   }
}

/**
 * Aufgabe 3: Erkennt Hexadezimalzahlen wie in Java, z. B. 0x1F, 0xFF, 0x7
 * (vereinfacht: nur Großbuchstaben A bis F).
 * Hexzahl = "0" "x" HexZiffer {HexZiffer}.
 * HexZiffer = "0" | "1" | … | "9" | "A" | "B" | … | "F".
 * LÖSUNG (Lehrkräfte)
 */
public class Hexzahl extends DEA {

   // TODO 3a
   public void zustandWechseln(char zeichen) {
      switch (zustand) {
         case 0:
            if (zeichen == '0') {
               zustand = 1;
            } else {
               zustand = ZF;
            }
            break;
         case 1:
            if (zeichen == 'x') {
               zustand = 2;
            } else {
               zustand = ZF;
            }
            break;
         case 2:
            if (istHexZiffer(zeichen)) {
               zustand = 3;
            } else {
               zustand = ZF;
            }
            break;
         case 3:
            if (istHexZiffer(zeichen)) {
               zustand = 3;
            } else {
               zustand = ZF;
            }
            break;
         default:
            zustand = ZF;
      }
   }

   // TODO 3b
   public boolean istEndzustand() {
      return zustand == 3;
   }

   // true, wenn zeichen eine der Hex-Ziffern 0 bis 9 oder A bis F ist
   private boolean istHexZiffer(char zeichen) {
      return "0123456789ABCDEF".indexOf(zeichen) >= 0;
   }
}

/**
 * Selbsttest des Projekts. Bitte nicht verändern!
 * Starten: Klick auf das kleine Dreieck links neben "@Test"
 * (ganz oben: alle Tests) oder auf der Website "Tests starten".
 */
public class DEATest {

   @Test
   public void bezeichnerFertig() {
      Bezeichner b = new Bezeichner();
      Assertions.assertTrue(b.pruefe("zahl2"), "Bezeichner: zahl2 ist ein Name.");
      Assertions.assertFalse(b.pruefe("2zahl"), "Bezeichner: 2zahl beginnt mit einer Ziffer.");
      Assertions.assertFalse(b.pruefe(""), "Bezeichner: Das leere Wort ist kein Name.");
   }

   @Test
   public void ganzeZahlen() {
      Kommazahl k = new Kommazahl();
      Assertions.assertTrue(k.pruefe("42"), "Aufgabe 2: 42 muss weiterhin akzeptiert werden.");
      Assertions.assertTrue(k.pruefe("7"), "Aufgabe 2: 7 muss weiterhin akzeptiert werden.");
      Assertions.assertFalse(k.pruefe(""), "Aufgabe 2: Das leere Wort ist keine Zahl.");
   }

   @Test
   public void kommazahlenAkzeptiert() {
      Kommazahl k = new Kommazahl();
      Assertions.assertTrue(k.pruefe("3.14"), "Aufgabe 2: 3.14 muss akzeptiert werden (TODO 2a bis 2c).");
      Assertions.assertTrue(k.pruefe("0.5"), "Aufgabe 2: 0.5 muss akzeptiert werden (TODO 2a bis 2c).");
   }

   @Test
   public void kommazahlenAbgelehnt() {
      Kommazahl k = new Kommazahl();
      Assertions.assertFalse(k.pruefe("3."), "Aufgabe 2: 3. endet in Z2, das ist kein Endzustand.");
      Assertions.assertFalse(k.pruefe(".5"), "Aufgabe 2: .5 beginnt nicht mit einer Ziffer.");
      Assertions.assertFalse(k.pruefe("1.2.3"), "Aufgabe 2: 1.2.3 hat zwei Punkte.");
      Assertions.assertFalse(k.pruefe("3,14"), "Aufgabe 2: Java schreibt Kommazahlen mit Punkt, nicht mit Komma.");
   }

   @Test
   public void hexzahlenAkzeptiert() {
      Hexzahl h = new Hexzahl();
      Assertions.assertTrue(h.pruefe("0x1F"), "Aufgabe 3: 0x1F muss akzeptiert werden.");
      Assertions.assertTrue(h.pruefe("0xFF"), "Aufgabe 3: 0xFF muss akzeptiert werden.");
      Assertions.assertTrue(h.pruefe("0x7"), "Aufgabe 3: 0x7 muss akzeptiert werden.");
   }

   @Test
   public void hexzahlenAbgelehnt() {
      Hexzahl h = new Hexzahl();
      Assertions.assertFalse(h.pruefe("0x"), "Aufgabe 3: Nach 0x muss mindestens eine Hex-Ziffer folgen.");
      Assertions.assertFalse(h.pruefe("1F"), "Aufgabe 3: Eine Hexzahl beginnt mit 0x.");
      Assertions.assertFalse(h.pruefe("0x1G"), "Aufgabe 3: G ist keine Hex-Ziffer.");
      Assertions.assertFalse(h.pruefe("00x1"), "Aufgabe 3: Nach der 0 muss das x kommen.");
      Assertions.assertFalse(h.pruefe(""), "Aufgabe 3: Das leere Wort ist keine Hexzahl.");
   }
}
